return (async () => {
// Parse CV: read n8n binary data from memory or filesystem-v2 storage.
function detectType(buffer, filename) {
  const nameLower = (filename || '').toLowerCase();
  if (buffer.length >= 4) {
    if (buffer[0] === 0x25 && buffer[1] === 0x50 && buffer[2] === 0x44 && buffer[3] === 0x46) return 'pdf';
    if (buffer[0] === 0x50 && buffer[1] === 0x4B) return 'docx';
  }
  if (nameLower.endsWith('.pdf')) return 'pdf';
  if (nameLower.endsWith('.docx')) return 'docx';
  if (nameLower.endsWith('.txt')) return 'txt';
  return 'unsupported';
}
function extractTextPdf(buf) {
  const t = buf.toString('utf8');
  const m = t.match(/[\x20-\x7E]{4,}/g);
  return m ? m.join(' ') : '';
}
const inputItems = $input.all();
const items = [];
for (let index = 0; index < inputItems.length; index++) {
  const item = inputItems[index];
  const raw = item.json || {};
  let fileBuffer = Buffer.alloc(0);
  if (raw.file?.data && raw.file.data !== 'filesystem-v2') {
    fileBuffer = Buffer.from(raw.file.data, 'base64');
  } else if (item.binary?.data) {
    fileBuffer = await this.helpers.getBinaryDataBuffer(index, 'data');
  }
  const filename = raw.file?.fileName || raw.file?.name || item.binary?.data?.fileName || '';
  const type = detectType(fileBuffer, filename);
  let textCV = '', errorFlag = '';
  if (type === 'pdf') { textCV = extractTextPdf(fileBuffer); if (!textCV.trim()) { errorFlag = 'parse_error'; textCV = ''; } }
  else if (type === 'docx') { textCV = ''; errorFlag = 'parse_error'; }
  else if (type === 'txt') { textCV = fileBuffer.toString('utf8'); }
  else { errorFlag = 'format_unsupported'; textCV = ''; }
  items.push({ json: { ...raw, textCV, cvFileType: type, parseErrorFlag: errorFlag } });
}
return items;
})();

// Rule Check - normalisasi konsisten untuk kriteria dan CV
const normalize = (value) => String(value ?? '')
  .toLowerCase()
  .replace(/[^\w\s+#]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();
const cleanCriterion = (value) => {
  let criterion = String(value ?? '').trim();
  const lower = criterion.toLowerCase();
  if (lower.startsWith('skill:')) criterion = criterion.slice(6).trim();
  else if (lower.startsWith('pengalaman:')) criterion = criterion.slice(11).trim();
  else if (lower.startsWith('pendidikan:')) criterion = criterion.slice(11).trim();
  return criterion;
};
const items = [];
for (const item of $input.all()) {
  const d = item.json;
  const textCV = normalize(d.textCV || '');
  const compactCV = textCV.replace(/\s/g, '');
  const raw = Array.isArray(d.kriteria)
    ? d.kriteria
    : String(d.kriteria || '').split(/[,;\n]+/).filter(Boolean);
  const criteria = raw.map(cleanCriterion).filter(Boolean);
  const passed = [];
  const failed = [];
  for (const criterion of criteria) {
    const normalized = normalize(criterion);
    const found = textCV.includes(normalized)
      || compactCV.includes(normalized.replace(/\s/g, ''));
    (found ? passed : failed).push(criterion);
  }
  const ok = failed.length === 0;
  items.push({ json: {
    ...d,
    ruleCheck: ok ? 'Memenuhi' : 'Tidak Memenuhi',
    alasanRuleCheck: ok ? 'Semua kriteria wajib terpenuhi'
      : 'Kriteria tidak terpenuhi: ' + failed.join(', '),
    kriteriaTerpenuhi: passed,
    kriteriaGagal: failed,
  } });
}
return items;

// Cabang TIDAK LOLOS rule check -> set skor 0, kategori Low
const items = [];
for (const item of $input.all()) {
  const d = item.json;
  items.push({
    json: {
      ...d,
      skorLLM: 0,
      alasanSkor: 'Gagal rule check awal: ' + (d.alasanRuleCheck || ''),
      skillTerdeteksi: '',
      enrichmentNotes: '',
      kategori: 'Low',
      alasanKategori: 'Gagal di tahap rule check (skor 0)',
      kategoriLabel: 'Belum Sesuai',
      errorFlag: d.parseErrorFlag || 'rule_check_failed'
    }
  });
}
return items;

// LLM Scoring dengan Exponential Backoff Retry (3x: 1s, 3s, 7s)
return (async () => {
  async function callLLMWithRetry(payload, config, maxRetries = 3) {
    const baseDelay = 1000;
    const multiplier = 3;

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      try {

        const data = await helpers.httpRequest({
          method: 'POST',
          url: config.apiUrl,
          headers: {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + config.apiKey
          },
          body: payload,
          json: true
        });
        return data.choices?.[0]?.message?.content || data.content || '';
      } catch (err) {
        if (attempt >= maxRetries) throw err;
        const delay = baseDelay * Math.pow(multiplier, attempt);
        await new Promise(r => setTimeout(r, delay));
      }
    }
  }

  function parseLLMResponse(raw) {
    if (!raw) return null;
    let content = String(raw).trim();
    const fenceMatch = content.match(/```(?:json)?\s*([\s\S]*?)```/);
    if (fenceMatch) content = fenceMatch[1].trim();
    try { return JSON.parse(content); } catch (_) {}
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    if (jsonMatch) { try { return JSON.parse(jsonMatch[0]); } catch (_) {} }
    return null;
  }

  function normalizeScore(raw) {
    const s = Number(raw);
    return isNaN(s) ? null : Math.max(0, Math.min(100, s));
  }

  const items = [];
  for (const item of $input.all()) {
    const d = item.json;
    const apiKey = $env.LLM_API_KEY;
    const apiUrl = $env.LLM_API_URL;
    const model = $env.LLM_MODEL || 'default';


    const kriteriaCsv = Array.isArray(d.kriteria) ? d.kriteria.join(', ') : String(d.kriteria || '');
    const payload = {
      model,
      messages: [
        { role: 'system', content: 'Anda asisten perekrut. Nilai kesesuaian CV dengan kriteria. Deteksi skill ekuivalen/superior (contoh Adobe Premiere > Capcut). Hitung skor 0-100. Balas JSON: {"skor": <0-100>, "skill_terdeteksi": [...], "alasan_llm": "...", "enrichment_notes": "..."} dalam Bahasa Indonesia.' },
        { role: 'user', content: 'Lowongan: ' + (d.lowongan || '') + '\nKriteria: ' + kriteriaCsv + '\nCV: ' + (d.textCV || '') }
      ],
      temperature: 0.2,
      response_format: { type: 'json_object' }
    };

    try {
      if (!apiKey || !apiUrl) throw new Error('LLM config missing');
      const rawContent = await callLLMWithRetry(payload, { apiKey, apiUrl, model }, 3);
      const parsed = parseLLMResponse(rawContent);

      if (parsed) {
        const skor = normalizeScore(parsed.skor);
        if (skor !== null) {
          items.push({ json: { ...d, skorLLM: skor, skillTerdeteksi: Array.isArray(parsed.skill_terdeteksi) ? parsed.skill_terdeteksi.join(', ') : String(parsed.skill_terdeteksi || ''), alasanSkor: String(parsed.alasan_llm || ''), enrichmentNotes: String(parsed.enrichment_notes || ''), errorFlag: '', llmRetries: 3 } });
          continue;
        }
      }
      throw new Error('LLM parse failed');
    } catch (err) {
      const textCV = (d.textCV || '').toLowerCase().replace(/[.\s]/g, '');
      const kriteria = Array.isArray(d.kriteria) ? d.kriteria : [];
      const bobotSkill = Number(d.bobotSkill) || 0.40;
      const bobotExp = Number(d.bobotPengalaman) || 0.35;
      const bobotEdu = Number(d.bobotPendidikan) || 0.25;

      function scoreComponent(items) {
        if (items.length === 0) return 100;
        let hit = 0;
        for (const k of items) {
          const key = String(k).toLowerCase().replace(/[.\s]/g, '');
          if (key && textCV.includes(key)) hit++;
        }
        return (hit / items.length) * 100;
      }

      const skillK = kriteria.filter(k => !String(k).toLowerCase().startsWith('pengalaman:') && !String(k).toLowerCase().startsWith('pendidikan:'));
      const expK = kriteria.filter(k => String(k).toLowerCase().startsWith('pengalaman:')).map(k => String(k).slice(11).trim());
      const eduK = kriteria.filter(k => String(k).toLowerCase().startsWith('pendidikan:')).map(k => String(k).slice(11).trim());

      const skor = Math.round(scoreComponent(skillK) * bobotSkill + scoreComponent(expK) * bobotExp + scoreComponent(eduK) * bobotEdu);

      items.push({ json: { ...d, skorLLM: skor, skillTerdeteksi: '', alasanSkor: 'Fallback rule-based (LLM gagal: ' + err.message + ')', enrichmentNotes: '', errorFlag: (!apiKey || !apiUrl) ? 'llm_config_missing' : 'llm_fallback', llmRetries: 3 } });
    }
  }
  return items;
})();

// Rule Kategori (Tahap 3): map skor -> kategori berdasarkan ambang
const items = [];
for (const item of $input.all()) {
  const d = item.json;
  let ambangHigh = 80, ambangLow = 40;
  if (!isNaN(parseInt(d.ambangHigh,10))) ambangHigh = parseInt(d.ambangHigh,10);
  if (!isNaN(parseInt(d.ambangLow,10))) ambangLow = parseInt(d.ambangLow,10);
  let skor = Number(d.skorLLM ?? 0);
  if (isNaN(skor)) skor = 0;
  skor = Math.max(0, Math.min(100, skor));
  let kategori, label, alasan;
  if (skor >= ambangHigh) { kategori='High'; label='Layak Lanjut'; alasan='Skor '+skor+' ≥ '+ambangHigh; }
  else if (skor >= ambangLow) { kategori='Medium'; label='Perlu Ditinjau'; alasan='Skor '+skor+' di antara '+ambangLow+'-'+ambangHigh; }
  else { kategori='Low'; label='Belum Sesuai'; alasan='Skor '+skor+' < '+ambangLow; }
  items.push({ json: { ...d, skorLLM: skor, kategori, kategoriLabel: label, alasanKategori: alasan } });
}
return items;

// Merge kedua cabang (LLM path + reject path) - sudah punya kategori
const items = [];
for (const item of $input.all()) {
  items.push({ json: item.json });
}
return items;

// E2E-safe dedup: Sheets lookup runs first, candidate comes from Merge Paths.
const referencedExisting = $('Baca Data Existing (Sheets)').all();
const existingRows = referencedExisting.length ? referencedExisting : $input.all();
const referencedCandidates = $('Merge Paths').all();
const candidateItems = referencedCandidates.length ? referencedCandidates : $input.all();
const now = Date.now();
const dayMs = 24 * 60 * 60 * 1000;
const existingSet = new Set();
for (const row of existingRows) {
  const j = row.json || {};
  const email = String(j.Email || j.email || j.C || '').trim().toLowerCase();
  const lowongan = String(j.Lowongan || j.lowongan || j.E || '').trim().toLowerCase();
  const ts = new Date(j.Timestamp || j.timestamp || j.A || 0).getTime();
  if (email && lowongan && !Number.isNaN(ts) && (now - ts) < dayMs) {
    existingSet.add(email + '|' + lowongan);
  }
}
return candidateItems.map((item) => {
  const d = item.json || {};
  const email = String(d.email || '').trim().toLowerCase();
  const lowongan = String(d.lowongan || '').trim().toLowerCase();
  const isDuplicate = existingSet.has(email + '|' + lowongan);
  return { json: { ...d, isDuplicate, skipWrite: isDuplicate } };
});

// Duplicate: skip write, set audit flag
const items = [];
for (const item of $input.all()) {
  const d = item.json;
  items.push({ json: { ...d, auditEventType: 'duplicate_skipped', auditDetail: 'Duplicate email+lowongan within 24h: ' + d.email, autoReplyStatus: 'N/A', notifStatus: 'N/A' } });
}
return items;

const items = [];
for (const item of $input.all()) {
  const d = item.json;
  const isLow = d.kategori === 'Low';
  const notifStatus = isLow ? 'N/A' : 'Pending';
  const autoReplyStatus = isLow ? 'Pending' : 'N/A';
  const row = [
    new Date().toISOString(), d.nama || '', d.email || '', d.noHP || '', d.lowongan || '', d.urlCV || '',
    d.ruleCheck || '', d.alasanRuleCheck || '', d.skillTerdeteksi || '', d.skorLLM ?? '', d.alasanSkor || '',
    d.enrichmentNotes || '', d.kategori || '', d.alasanKategori || '', d.kategoriLabel || '', notifStatus,
    autoReplyStatus, '', d.errorFlag || ''
  ];
  items.push({ json: {
    ...d,
    Timestamp: row[0], Nama: row[1], Email: row[2], 'No HP': row[3], Lowongan: row[4], 'URL CV': row[5],
    'Rule Check': row[6], 'Alasan Rule Check': row[7], 'Skill Terdeteksi': row[8], 'Skor LLM': row[9],
    'Alasan Skor': row[10], 'Enrichment Notes': row[11], Kategori: row[12], 'Alasan Kategori': row[13],
    'Kategori Label': row[14], 'Status Notifikasi HR': row[15], 'Status Auto-Reply': row[16],
    'Waktu Auto-Reply': row[17], 'Error Flag': row[18], sheetRow: row, autoReplyStatus, notifStatus,
    auditEventType: d.auditEventType || 'pipeline_end'
  } });
}
return items;

const sourceItems = $input.all();
const prior = $('Tulis ke Google Sheets').first().json || {};
return sourceItems.map((item) => {
  const d = item.json || {};
  const candidate = d.email ? d : { ...prior, ...d };
  const notifStatus = candidate.kategori === 'High' || candidate.kategori === 'Medium' ? 'Terkirim' : 'N/A';
  const autoReplyStatus = candidate.kategori === 'Low' ? 'Pending' : 'N/A';
  return { json: { ...candidate, notifStatus, autoReplyStatus, auditEventType: candidate.auditEventType || 'pipeline_end' } };
});

const items = [];
for (const item of $input.all()) {
  const d = item.json;
  const timestamp = new Date().toISOString();
  const eventType = d.auditEventType || 'pipeline_end';
  const emailKandidat = d.email || '';
  const lowongan = d.lowongan || '';
  const detail = 'Kandidat ' + (d.nama || '') + ' → kategori ' + (d.kategori || '') + ' (skor ' + (d.skorLLM ?? '') + ')';
  items.push({ json: {
    timestamp, eventType, emailKandidat, lowongan, detail, status: 'Success',
    Timestamp: timestamp, 'Event Type': eventType, 'Email Kandidat': emailKandidat, Lowongan: lowongan,
    Detail: detail, Status: 'Success'
  } });
}
return items;

// Sheets Write Error Handler: buffer fallback + audit
const items = [];
for (const item of $input.all()) {
  const d = item.json;
  const error = d.error || d.lastError || 'Unknown sheets error';
  const bufferEntry = {
    timestamp: new Date().toISOString(),
    kandidat_email: d.email || '',
    lowongan: d.lowongan || '',
    data: { ...d, sheetRow: d.sheetRow },
    retry_count: 0,
    max_retry: 10,
    next_retry: new Date(Date.now() + 5*60*1000).toISOString()
  };
  items.push({
    json: {
      ...d,
      bufferEntry: JSON.stringify(bufferEntry),
      auditEventType: 'buffer_written',
      auditDetail: 'Sheets write failed, buffered: ' + error,
      notifStatus: 'N/A',
      autoReplyStatus: 'N/A'
    }
  });
}
return items;

const current = $input.first().json || {};
const candidate = $('Set Status Email').first().json || {};
return [{ json: { ...candidate, ...current } }];
